var any interface{} = time.Second // (time.Duration, 1000000000)
// The interface carries both the dynamic type and the value;
// reflect reads each half separately:
fmt.Println(reflect.TypeOf(any))  // time.Duration  (the type word)
fmt.Println(reflect.ValueOf(any)) // 1s             (the value word)
// A nil interface has no type, so TypeOf(nil) returns nil:
fmt.Println(reflect.TypeOf(nil) == nil) // true

type Greeter struct{ Prefix string }

func (g Greeter) Greet(name string) string {
	return g.Prefix + " " + name
}

func main() {
	v := reflect.ValueOf(Greeter{Prefix: "Hello"})
	m := v.MethodByName("Greet") // looked up at runtime
	args := []reflect.Value{reflect.ValueOf("Ada")}
	out := m.Call(args)          // returns []reflect.Value
	fmt.Println(out[0].String()) // Hello Ada
