package solution

import (
	"reflect"
	"strconv"
)

// SetDefaults fills zero-valued exported fields from their `default` tag.
func SetDefaults(ptr interface{}) {
	v := reflect.ValueOf(ptr)
	if v.Kind() != reflect.Ptr || v.IsNil() {
		return // need a non-nil pointer to mutate the original
	}
	v = v.Elem() // dereference to the addressable struct
	if v.Kind() != reflect.Struct {
		return
	}
	t := v.Type()
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		def, ok := t.Field(i).Tag.Lookup("default")
		if !ok || !field.CanSet() || !field.IsZero() {
			continue // skip: no tag, unexported, or already set
		}
		switch field.Kind() {
		case reflect.String:
			field.SetString(def)
		case reflect.Int, reflect.Int64:
			if n, err := strconv.ParseInt(def, 10, 64); err == nil {
				field.SetInt(n)
			}
		}
	}
}

