package solution

import "testing"

type Config struct {
	Host    string `default:"localhost"`
	Port    int    `default:"8080"`
	Timeout int    // no tag: untouched
}

func TestSetDefaults(t *testing.T) {
	c := Config{Port: 9000} // Port already set; should stay
	SetDefaults(&c)
	if c.Host != "localhost" {
		t.Errorf("Host = %q want localhost", c.Host)
	}
	if c.Port != 9000 {
		t.Errorf("Port = %d want 9000 (already set)", c.Port)
	}
	if c.Timeout != 0 {
		t.Errorf("Timeout = %d want 0 (no default tag)", c.Timeout)
	}
}

