func fill(v interface{}) {
	rv := reflect.ValueOf(v).Elem() // v is *User; Elem() is addressable
	f := rv.FieldByName("Name")
	if f.CanSet() {                 // exported & addressable?
		f.SetString("Ada")
	}
}

func main() {
	u := User{}
	fill(&u) // pass a pointer
	fmt.Println(u.Name) // Ada
}

func StructToMap(v interface{}) map[string]interface{} {
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Ptr {
		rv = rv.Elem() // dereference *T -> T
	}
	out := make(map[string]interface{})
	if rv.Kind() != reflect.Struct {
		return out
	}
	t := rv.Type()
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.PkgPath != "" {
			continue // unexported field: PkgPath is non-empty
		}
		name := f.Name
		if tag := f.Tag.Get("json"); tag != "" && tag != "-" {
			if comma := strings.IndexByte(tag, ','); comma >= 0 {
				tag = tag[:comma] // strip options like ,omitempty
			}
			if tag != "" {
				name = tag
			}
		}
		out[name] = rv.Field(i).Interface()
	}
	return out
}

func SetFields(ptr interface{}, values map[string]interface{}) error {
	rv := reflect.ValueOf(ptr)
	if rv.Kind() != reflect.Ptr || rv.IsNil() {
		return fmt.Errorf("SetFields: need non-nil pointer, got %T", ptr)
	}
	rv = rv.Elem() // addressable struct
	if rv.Kind() != reflect.Struct {
		return fmt.Errorf("SetFields: need pointer to struct, got %s", rv.Kind())
	}
	for name, val := range values {
		f := rv.FieldByName(name)
		if !f.IsValid() {
			continue // no such field
		}
		if !f.CanSet() {
			continue // unexported: reflect won't set it
		}
		vv := reflect.ValueOf(val)
		switch {
		case vv.Type().AssignableTo(f.Type()):
			f.Set(vv)
		case vv.Type().ConvertibleTo(f.Type()):
			f.Set(vv.Convert(f.Type()))
		default:
			return fmt.Errorf("field %q: cannot assign %s to %s", name, vv.Type(), f.Type())
		}
	}
	return nil
}

